import type { Metadata } from 'next'
import './globals.css'

export const metadata: Metadata = {
  title: 'BlueArkive — The Sovereign Memory Fabric',
  description:
    'Private AI meeting notes that run 100% locally on your machine. No bots. No cloud. No fees. Free forever.',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="anonymous" />
        <link
          href="https://fonts.googleapis.com/css2?family=Poppins:ital,wght@0,300;0,400;0,500;0,600;0,700&family=Source+Serif+4:ital,wght@0,400;0,500;1,400;1,500&display=swap"
          rel="stylesheet"
        />
      </head>
      <body suppressHydrationWarning>{children}</body>
    </html>
  )
}

'use client'

import { motion } from 'framer-motion'
import { useState, useEffect } from 'react'

const quotes = [
  "It's like having a brilliant intern who never misses anything.",
  'I can finally use an AI tool without my IT team screaming at me.',
  'I kept waiting for the paywall. It never came.',
  "It doesn't destroy my MacBook Air battery.",
  "I asked 'What did we decide?' and it pulled answers from three meetings ago.",
  'The 0 cloud uploads gives me total peace of mind.',
]

export function VocMarquee() {
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  if (!mounted) return null

  return (
    <div
      className="voc-marquee-section"
      style={{ overflow: 'hidden', padding: '4rem 0', position: 'relative', zIndex: 10 }}
    >
      <div className="voc-marquee-track" style={{ display: 'flex', whiteSpace: 'nowrap' }}>
        <motion.div
          initial={{ x: 0 }}
          animate={{ x: '-50%' }}
          transition={{
            repeat: Infinity,
            ease: 'linear',
            duration: 40,
          }}
          style={{ display: 'flex', gap: '2rem', paddingRight: '2rem' }}
        >
          {/* Double the array for seamless infinite scroll */}
          {[...quotes, ...quotes].map((quote, i) => (
            <div
              key={i}
              className="voc-quote liquid-glass"
              style={{
                padding: '1.5rem 2rem',
                borderRadius: '1rem',
                fontSize: '0.9375rem',
                color: 'rgba(255, 255, 255, 0.85)',
                fontWeight: 500,
                fontFamily: 'var(--font-serif)',
                fontStyle: 'italic',
                flexShrink: 0,
              }}
            >
              &quot;{quote}&quot;
            </div>
          ))}
        </motion.div>
      </div>
    </div>
  )
}
